import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { betaLocales, launchLocales } from "../src/locales.ts";

/**
 * Writes src/catalogs.generated.ts from the namespace files in messages/<locale>/<namespace>.json.
 * One file per namespace lets agents add copy in parallel without editing a shared catalog.
 * With --check, writes nothing and exits 1 when a generated file is out of date.
 *
 * Launch locales (en-US, es-US) must hold exactly the namespaces of en-US. A Beta locale (Section 15,
 * ADR 0053) may hold any of them, or none: the Google Translate pipeline (ADR 0037) writes them, and
 * every key a Beta catalog lacks falls back to en-US. Each Beta locale gets its own module,
 * src/beta/<locale>.generated.ts, which src/load.ts imports only when that locale is asked for, so no
 * bundle carries every catalog.
 */
const root = fileURLToPath(new URL("../", import.meta.url));
const LOCALES = launchLocales;
const NAMESPACE = /^[a-z][a-zA-Z0-9]*$/;

const ident = (locale: string, ns: string) => `${locale.replace("-", "")}_${ns}`;

const namespaces = readdirSync(`${root}messages/en-US`)
  .filter((f) => f.endsWith(".json"))
  .map((f) => f.slice(0, -".json".length))
  .sort();

for (const ns of namespaces) {
  if (!NAMESPACE.test(ns)) {
    console.error(`Namespace file ${ns}.json must be named in camelCase (letters and digits).`);
    process.exit(1);
  }
}
for (const locale of LOCALES.slice(1)) {
  const theirs = readdirSync(`${root}messages/${locale}`)
    .filter((f) => f.endsWith(".json"))
    .map((f) => f.slice(0, -".json".length))
    .sort();
  if (JSON.stringify(theirs) !== JSON.stringify(namespaces)) {
    console.error(`messages/${locale} must hold exactly the namespaces of messages/en-US.`);
    process.exit(1);
  }
}

/** The namespace files a Beta locale holds today; an absent directory holds none. */
function betaNamespaces(locale: string): string[] {
  const dir = `${root}messages/${locale}`;
  if (!existsSync(dir)) return [];
  const theirs = readdirSync(dir)
    .filter((f) => f.endsWith(".json"))
    .map((f) => f.slice(0, -".json".length))
    .sort();
  const unknown = theirs.filter((ns) => !namespaces.includes(ns));
  if (unknown.length > 0) {
    console.error(
      `messages/${locale} holds ${unknown.map((ns) => `${ns}.json`).join(", ")}, which messages/en-US does not.`,
    );
    process.exit(1);
  }
  return theirs;
}

const lines = [
  "// Generated by `pnpm --filter @xos/i18n generate:catalogs` from messages/<locale>/*.json.",
  "// Never edit by hand. On a merge conflict, rerun the generator.",
  "",
  ...LOCALES.flatMap((locale) =>
    namespaces.map(
      (ns) =>
        `import ${ident(locale, ns)} from "../messages/${locale}/${ns}.json" with { type: "json" };`,
    ),
  ),
  "",
  ...LOCALES.flatMap((locale) => [
    `export const ${locale.replace("-", "")} = {`,
    ...namespaces.map((ns) => `  ${ns}: ${ident(locale, ns)},`),
    "};",
    "",
  ]),
];

/**
 * Client extracts (A24-009): a few message subtrees that a client component needs where no
 * provider exists, such as a global error boundary. They are copied into src/extracts.generated.ts
 * so that component imports a few strings instead of a whole namespace file.
 */
const extracts = JSON.parse(readFileSync(`${root}client-extracts.json`, "utf8")) as Record<
  string,
  string
>;

function subtree(locale: string, path: string): unknown {
  const [ns, ...rest] = path.split(".");
  let node: unknown = JSON.parse(readFileSync(`${root}messages/${locale}/${ns}.json`, "utf8"));
  for (const key of rest) {
    node =
      typeof node === "object" && node !== null
        ? (node as Record<string, unknown>)[key]
        : undefined;
  }
  if (typeof node !== "object" || node === null) {
    console.error(`client-extracts.json: ${path} is not a message group in ${locale}.`);
    process.exit(1);
  }
  return node;
}

/** A TypeScript object literal in the repository's Prettier style. */
function literal(value: unknown, indent: string): string {
  if (typeof value !== "object" || value === null) return JSON.stringify(value);
  const inner = `${indent}  `;
  const entries = Object.entries(value).map(([k, v]) => {
    const key = /^[A-Za-z_$][\w$]*$/.test(k) ? k : JSON.stringify(k);
    return `${inner}${key}: ${literal(v, inner)},`;
  });
  return `{\n${entries.join("\n")}\n${indent}}`;
}

const extractLines = [
  "// Generated by `pnpm --filter @xos/i18n generate:catalogs` from client-extracts.json.",
  "// Never edit by hand. On a merge conflict, rerun the generator.",
  "",
  ...Object.keys(extracts)
    .sort()
    .flatMap((name) => {
      const path = extracts[name] ?? "";
      const body = Object.fromEntries(LOCALES.map((l) => [l, subtree(l, path)]));
      return [`/** ${path} */`, `export const ${name} = ${literal(body, "")} as const;`, ""];
    }),
];

/** One Beta locale's module: the namespace files it holds today, typed as a partial catalog. */
function betaModule(locale: string): string {
  const held = betaNamespaces(locale);
  return [
    `// Generated by \`pnpm --filter @xos/i18n generate:catalogs\` from messages/${locale}/*.json.`,
    "// Never edit by hand. On a merge conflict, rerun the generator.",
    `// A Beta catalog (ADR 0053): ${held.length} of ${namespaces.length} namespaces; every missing key reads en-US.`,
    "",
    'import type { PartialMessages } from "../fallback.ts";',
    ...held.map(
      (ns) =>
        `import ${ident(locale, ns)} from "../../messages/${locale}/${ns}.json" with { type: "json" };`,
    ),
    "",
    ...(held.length === 0
      ? ["export const catalog: PartialMessages = {};"]
      : [
          "export const catalog: PartialMessages = {",
          ...held.map((ns) => `  ${ns}: ${ident(locale, ns)},`),
          "};",
        ]),
    "",
  ].join("\n");
}

const betaIndex = [
  "// Generated by `pnpm --filter @xos/i18n generate:catalogs` from the Beta locales in src/locales.ts.",
  "// Never edit by hand. On a merge conflict, rerun the generator.",
  "",
  'import type { PartialMessages } from "./fallback.ts";',
  'import type { BetaLocale } from "./locales.ts";',
  "",
  "/** Loads one Beta locale's catalog on demand (ADR 0053), so no bundle carries all of them. */",
  "export const betaCatalogs: Record<BetaLocale, () => Promise<PartialMessages>> = {",
  ...betaLocales.map(
    (locale) =>
      `  "${locale}": () => import("./beta/${locale}.generated.ts").then((m) => m.catalog),`,
  ),
  "};",
  "",
].join("\n");

const outputs: Record<string, string> = {
  "src/catalogs.generated.ts": lines.join("\n"),
  "src/extracts.generated.ts": extractLines.join("\n"),
  "src/beta.generated.ts": betaIndex,
  ...Object.fromEntries(
    betaLocales.map((locale) => [`src/beta/${locale}.generated.ts`, betaModule(locale)]),
  ),
};

if (process.argv.includes("--check")) {
  for (const [file, output] of Object.entries(outputs)) {
    let current = "";
    try {
      current = readFileSync(`${root}${file}`, "utf8");
    } catch (error) {
      console.error(`Cannot read ${file}: ${String(error)}`);
      process.exit(1);
    }
    if (current !== output) {
      console.error(`${file} is out of date. Run generate:catalogs.`);
      process.exit(1);
    }
  }
  console.log("The generated catalog modules match the message files.");
} else {
  mkdirSync(`${root}src/beta`, { recursive: true });
  for (const [file, output] of Object.entries(outputs)) writeFileSync(`${root}${file}`, output);
  console.log(
    `Wrote src/catalogs.generated.ts with ${namespaces.length} namespaces, ${Object.keys(extracts).length} client extracts and ${betaLocales.length} Beta catalog modules.`,
  );
}
